      </FormControl>
      <Box sx={{ width: '100%' }}>
        <BarChart
          {...barChartsProps}
          highlightedAxis={highlightedAxis}
          onHighlightedAxisChange={(newState) => setHighlightedAxis(newState)}
        />
        <LineChart
          {...lineChartsProps}
          highlightedAxis={highlightedAxis}
          onHighlightedAxisChange={(newState) => setHighlightedAxis(newState)}
